import { useState, useEffect, useRef } from 'react';
import { Link, useParams } from 'react-router-dom';
import './Profile.css';

function Profile() {
  const { userId } = useParams();
  const [profile, setProfile] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isFollowing, setIsFollowing] = useState(false);
  const [posts, setPosts] = useState([]);
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [selectedFile, setSelectedFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState('');
  const fileInputRef = useRef(null);
  
  // Poze default
  const defaultAvatar = 'https://cdn.pixabay.com/photo/2015/10/05/22/37/blank-profile-picture-973460_960_720.png';
  const defaultPostImage = 'https://cdn.pixabay.com/photo/2017/11/10/05/24/add-2935429_960_720.png';

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const response = await fetch(`http://127.0.0.1:8000/profile/${userId}`);
        if (!response.ok) throw new Error('Profile not found');
        const data = await response.json();
        setProfile(data);
        setIsFollowing(data.isFollowing || false);
        setPreviewUrl(data.avatar || defaultAvatar);
      } catch (error) {
        console.error(error);
      } finally {
        setIsLoading(false);
      }
    };

    const fetchPosts = async () => {
      const response = await fetch(`http://127.0.0.1:8000/profile/${userId}/posts`);
      const data = await response.json();
      setPosts(data);
    };

    fetchProfile();
    fetchPosts();
  }, [userId]);

  const handleFollow = async () => {
    try {
      const response = await fetch(`http://127.0.0.1:8000/profile/${userId}/follow`, {
        method: isFollowing ? 'DELETE' : 'POST',
        headers: { 'Content-Type': 'application/json' },
      });
      
      if (response.ok) {
        setIsFollowing(!isFollowing);
      }
    } catch (error) {
      console.error('Error updating follow status:', error);
    }
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setSelectedFile(file);
    
    // Create preview
    const reader = new FileReader();
    reader.onloadend = () => {
      setPreviewUrl(reader.result);
    };
    reader.readAsDataURL(file);
  };

  const handleUpload = async () => {
    if (!selectedFile) return;

    const formData = new FormData();
    formData.append('avatar', selectedFile);

    try {
      const response = await fetch(`http://127.0.0.1:8000/profile/upload-avatar`, {
        method: 'POST',
        body: formData,
      });

      if (response.ok) {
        const data = await response.json();
        setProfile(prev => ({ ...prev, avatar: data.avatarUrl }));
        setShowUploadModal(false);
      }
    } catch (error) {
      console.error('Error uploading avatar:', error);
    }
  };

  const triggerFileInput = () => {
    fileInputRef.current.click();
  };

  if (isLoading) return <div className="loading">Loading profile...</div>;
  if (!profile) return <div className="error">Profile not found</div>;

  return (
    <div className="profile-container">
      {/* Modal pentru încărcare foto */}
      {showUploadModal && (
        <div className="upload-modal">
          <div className="upload-modal-content">
            <h3>Update Profile Photo</h3>
            <div className="avatar-preview">
              <img src={previewUrl} alt="Preview" />
            </div>
            <div className="upload-actions">
              <button onClick={triggerFileInput} className="btn-select">
                Select Photo
              </button>
              <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileChange}
                accept="image/*"
                style={{ display: 'none' }}
              />
              <button 
                onClick={handleUpload} 
                className="btn-upload"
                disabled={!selectedFile}
              >
                Upload
              </button>
              <button 
                onClick={() => setShowUploadModal(false)} 
                className="btn-cancel"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="profile-header">
        <div className="profile-avatar">
          <img 
            src={profile.avatar || defaultAvatar} 
            alt={profile.name}
            onError={(e) => {
              e.target.src = defaultAvatar;
            }}
          />
          {profile.isCurrentUser && (
            <button 
              className="edit-avatar-btn"
              onClick={() => setShowUploadModal(true)}
              title="Change profile photo"
            >
              <i className="fas fa-camera"></i>
            </button>
          )}
        </div>
        
        <div className="profile-info">
          <h1>{profile.name}</h1>
          <p className="username">@{profile.username}</p>
          <p className="bio">{profile.bio || 'No bio yet'}</p>
          
          <div className="profile-stats">
            <div>
              <strong>{profile.postsCount || 0}</strong>
              <span>Posts</span>
            </div>
            <div>
              <strong>{profile.followersCount || 0}</strong>
              <span>Followers</span>
            </div>
            <div>
              <strong>{profile.followingCount || 0}</strong>
              <span>Following</span>
            </div>
          </div>
          
          <button 
            onClick={handleFollow}
            className={`follow-btn ${isFollowing ? 'following' : ''}`}
            disabled={profile.isCurrentUser}
          >
            {isFollowing ? 'Following' : 'Follow'}
          </button>
        </div>
      </div>
      
      <div className="profile-content">
        <div className="profile-nav">
          <button className="active">Posts</button>
          <button>Photos</button>
          <button>Saved</button>
        </div>
        
        <div className="posts-grid">
          {posts.length > 0 ? (
            posts.map(post => (
              <div key={post.id} className="post-thumbnail">
                <img 
                  src={post.image || defaultPostImage} 
                  alt={`Post by ${profile.name}`}
                  onError={(e) => {
                    e.target.src = defaultPostImage;
                  }}
                />
                <div className="post-overlay">
                  <span>❤️ {post.likes}</span>
                  <span>💬 {post.comments}</span>
                </div>
              </div>
            ))
          ) : (
            <div className="no-posts">
              <p>No posts yet</p>
              {profile.isCurrentUser && (
                <Link to="/create-post" className="create-post-btn">
                  Create your first post
                </Link>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Profile;
